import { type AudioPlayer, createAudioPlayer, setAudioModeAsync } from 'expo-audio';

import { sound } from '@/design/tokens';

// Generated by scripts/gen-sounds.mjs.
const SOURCES = {
  tap: require('@/assets/sounds/tap.wav') as number,
  tick: require('@/assets/sounds/tick.wav') as number,
  pick: require('@/assets/sounds/pick.wav') as number,
  pickStamp: require('@/assets/sounds/pickStamp.wav') as number,
  toggleOn: require('@/assets/sounds/toggleOn.wav') as number,
  toggleOff: require('@/assets/sounds/toggleOff.wav') as number,
  blip: require('@/assets/sounds/blip.wav') as number,
};

export type SoundName = keyof typeof SOURCES;

// One player per sound for the app's lifetime: they are tiny, and re-creating them per press adds latency.
const players: Partial<Record<SoundName, AudioPlayer>> = {};
let ready: Promise<void> | null = null;
// Mirrors the Sound setting (settings store).
let enabled = true;

function report(error: unknown) {
  if (__DEV__) console.warn('Sound playback failed', error);
}

function player(name: SoundName) {
  let p = players[name];
  if (!p) {
    // By default iOS players deactivate the audio session ~100 ms after each sound, so the next one pays to
    // reactivate it on the press; with rapid blips that showed up as hitches.
    p = createAudioPlayer(SOURCES[name], { keepAudioSessionActive: true });
    p.volume = sound.volume;
    players[name] = p;
  }
  return p;
}

function configure() {
  // Respect the ringer switch and never interrupt the user's music or podcast.
  ready ??= setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers' });
  return ready;
}

/** Loads every sound up front so the first press isn't late. Call once at startup. */
export function preloadSounds() {
  configure().catch(report);
  for (const name of Object.keys(SOURCES) as SoundName[]) player(name);
}

export function setSoundEnabled(on: boolean) {
  enabled = on;
}

/** Plays a UI sound from the start, cutting off its previous play (they are all under 150 ms). */
export function playSound(name: SoundName) {
  if (!enabled) return;
  configure()
    .then(() => {
      const p = player(name);
      return p.seekTo(0).then(() => p.play());
    })
    .catch(report);
}
